"""
验证器模块

提供记忆、查询和配置的验证功能
"""

from dataclasses import dataclass
from datetime import datetime
from enum import Enum
from typing import Any, Dict, List, Optional, Set, Union


class MemoryValidationError(Exception):
    """记忆验证错误"""

    def __init__(
        self,
        message: str,
        field: Optional[str] = None,
        value: Any = None
    ):
        super().__init__(message)
        self.field = field
        self.value = value
        self.message = message

    def __str__(self) -> str:
        if self.field:
            return f"Validation error in '{self.field}': {self.message}"
        return f"Validation error: {self.message}"


@dataclass
class ValidationResult:
    """验证结果"""
    is_valid: bool
    errors: List[str]
    warnings: List[str]

    @classmethod
    def success(cls) -> "ValidationResult":
        return cls(is_valid=True, errors=[], warnings=[])

    @classmethod
    def failure(cls, errors: List[str]) -> "ValidationResult":
        return cls(is_valid=False, errors=errors, warnings=[])


def validate_memory(
    memory: Any,
    strict: bool = False
) -> ValidationResult:
    """
    验证记忆对象

    Args:
        memory: 记忆对象
        strict: 是否严格模式

    Returns:
        ValidationResult
    """
    errors: List[str] = []
    warnings: List[str] = []

    # 检查必需属性
    required_attrs = ['memory_id', 'content', 'memory_type', 'created_at']

    for attr in required_attrs:
        if not hasattr(memory, attr):
            errors.append(f"Missing required attribute: {attr}")
        elif getattr(memory, attr) is None:
            if strict:
                errors.append(f"Attribute '{attr}' cannot be None")
            else:
                warnings.append(f"Attribute '{attr}' is None")

    # 验证memory_id
    if hasattr(memory, 'memory_id') and memory.memory_id:
        memory_id = memory.memory_id
        if not isinstance(memory_id, str):
            errors.append("memory_id must be a string")
        elif len(memory_id) < 5:
            errors.append("memory_id is too short (min 5 chars)")
        elif len(memory_id) > 128:
            errors.append("memory_id is too long (max 128 chars)")

    # 验证content
    if hasattr(memory, 'content') and memory.content:
        content = memory.content
        if not isinstance(content, str):
            errors.append("content must be a string")
        elif len(content) == 0:
            errors.append("content cannot be empty")
        elif len(content) > 100000:
            warnings.append("content is very long (>100000 chars)")

    # 验证timestamps
    if hasattr(memory, 'created_at') and memory.created_at:
        if not isinstance(memory.created_at, datetime):
            errors.append("created_at must be a datetime object")

    if hasattr(memory, 'updated_at') and memory.updated_at:
        if not isinstance(memory.updated_at, datetime):
            errors.append("updated_at must be a datetime object")
        elif hasattr(memory, 'created_at') and memory.created_at:
            if memory.updated_at < memory.created_at:
                warnings.append("updated_at is earlier than created_at")

    # 验证priority
    if hasattr(memory, 'priority') and memory.priority is not None:
        priority = memory.priority
        if isinstance(priority, Enum):
            pass  # Enum类型总是有效的
        elif isinstance(priority, (int, float)):
            if priority < 0 or priority > 10:
                errors.append("priority must be between 0 and 10")

    # 验证importance_score
    if hasattr(memory, 'importance_score') and memory.importance_score is not None:
        score = memory.importance_score
        if not isinstance(score, (int, float)):
            errors.append("importance_score must be numeric")
        elif score < 0.0 or score > 1.0:
            errors.append("importance_score must be between 0.0 and 1.0")

    # 验证metadata
    if hasattr(memory, 'metadata') and memory.metadata is not None:
        if not isinstance(memory.metadata, dict):
            errors.append("metadata must be a dictionary")

    # 验证embedding
    if hasattr(memory, 'embedding') and memory.embedding is not None:
        embedding = memory.embedding
        if not isinstance(embedding, list):
            errors.append("embedding must be a list")
        elif len(embedding) == 0:
            warnings.append("embedding is empty")
        elif not all(isinstance(x, (int, float)) for x in embedding):
            errors.append("embedding must contain only numeric values")

    if errors:
        return ValidationResult.failure(errors)

    return ValidationResult(is_valid=True, errors=[], warnings=warnings)


def validate_query(
    query: Any,
    strict: bool = False
) -> ValidationResult:
    """
    验证查询对象

    Args:
        query: 查询对象
        strict: 是否严格模式

    Returns:
        ValidationResult
    """
    errors: List[str] = []
    warnings: List[str] = []

    # 检查query_text或embedding至少存在一个
    has_text = hasattr(query, 'query_text') and query.query_text
    has_embedding = hasattr(query, 'query_embedding') and query.query_embedding

    if not has_text and not has_embedding:
        errors.append("Query must have either query_text or query_embedding")

    # 验证limit
    if hasattr(query, 'limit') and query.limit is not None:
        limit = query.limit
        if not isinstance(limit, int):
            errors.append("limit must be an integer")
        elif limit <= 0:
            errors.append("limit must be positive")
        elif limit > 1000:
            warnings.append("limit is very large (>1000)")

    # 验证threshold
    if hasattr(query, 'threshold') and query.threshold is not None:
        threshold = query.threshold
        if not isinstance(threshold, (int, float)):
            errors.append("threshold must be numeric")
        elif threshold < 0.0 or threshold > 1.0:
            errors.append("threshold must be between 0.0 and 1.0")

    # 验证user_id
    if hasattr(query, 'user_id') and query.user_id:
        if not isinstance(query.user_id, str):
            errors.append("user_id must be a string")

    # 验证memory_types
    if hasattr(query, 'memory_types') and query.memory_types:
        if not isinstance(query.memory_types, (list, set)):
            errors.append("memory_types must be a list or set")

    # 验证时间范围
    if hasattr(query, 'start_time') and hasattr(query, 'end_time'):
        if query.start_time and query.end_time:
            if query.start_time > query.end_time:
                errors.append("start_time cannot be after end_time")

    if errors:
        return ValidationResult.failure(errors)

    return ValidationResult(is_valid=True, errors=[], warnings=warnings)


def validate_config(
    config: Dict[str, Any],
    schema: Optional[Dict[str, Any]] = None
) -> ValidationResult:
    """
    验证配置字典

    Args:
        config: 配置字典
        schema: 配置模式（可选）

    Returns:
        ValidationResult
    """
    errors: List[str] = []
    warnings: List[str] = []

    if not isinstance(config, dict):
        return ValidationResult.failure(["config must be a dictionary"])

    # 如果提供了schema，进行模式验证
    if schema:
        errors.extend(_validate_against_schema(config, schema, ""))

    # 通用验证规则

    # 验证Redis配置
    if 'redis' in config:
        redis_config = config['redis']
        if not isinstance(redis_config, dict):
            errors.append("redis config must be a dictionary")
        else:
            if 'host' not in redis_config:
                warnings.append("redis.host not specified, using default")
            if 'port' in redis_config:
                port = redis_config['port']
                if not isinstance(port, int) or port < 1 or port > 65535:
                    errors.append("redis.port must be a valid port number")

    # 验证向量数据库配置
    if 'vector_db' in config:
        vdb_config = config['vector_db']
        if not isinstance(vdb_config, dict):
            errors.append("vector_db config must be a dictionary")
        else:
            if 'type' in vdb_config:
                valid_types = ['chroma', 'milvus', 'qdrant', 'pinecone']
                if vdb_config['type'] not in valid_types:
                    errors.append(f"vector_db.type must be one of {valid_types}")
            if 'dimension' in vdb_config:
                dim = vdb_config['dimension']
                if not isinstance(dim, int) or dim < 1:
                    errors.append("vector_db.dimension must be a positive integer")

    # 验证Mem0配置
    if 'mem0' in config:
        mem0_config = config['mem0']
        if not isinstance(mem0_config, dict):
            errors.append("mem0 config must be a dictionary")
        else:
            if 'api_key' not in mem0_config and 'enabled' in mem0_config:
                if mem0_config.get('enabled', False):
                    errors.append("mem0.api_key is required when mem0 is enabled")

    # 验证Token配置
    if 'token' in config:
        token_config = config['token']
        if not isinstance(token_config, dict):
            errors.append("token config must be a dictionary")
        else:
            if 'max_context_tokens' in token_config:
                max_tokens = token_config['max_context_tokens']
                if not isinstance(max_tokens, int) or max_tokens < 100:
                    errors.append("token.max_context_tokens must be at least 100")

    # 验证层级配置
    for layer in ['l1', 'l2', 'l3']:
        if layer in config:
            layer_config = config[layer]
            if not isinstance(layer_config, dict):
                errors.append(f"{layer} config must be a dictionary")
            else:
                if 'max_size' in layer_config:
                    size = layer_config['max_size']
                    if not isinstance(size, int) or size < 1:
                        errors.append(f"{layer}.max_size must be a positive integer")
                if 'ttl' in layer_config:
                    ttl = layer_config['ttl']
                    if not isinstance(ttl, (int, float)) or ttl < 0:
                        errors.append(f"{layer}.ttl must be non-negative")

    if errors:
        return ValidationResult.failure(errors)

    return ValidationResult(is_valid=True, errors=[], warnings=warnings)


def _validate_against_schema(
    data: Dict[str, Any],
    schema: Dict[str, Any],
    path: str
) -> List[str]:
    """
    根据模式验证数据

    Args:
        data: 数据字典
        schema: 模式字典
        path: 当前路径

    Returns:
        错误列表
    """
    errors: List[str] = []

    # 检查必需字段
    required = schema.get('required', [])
    for field in required:
        if field not in data:
            field_path = f"{path}.{field}" if path else field
            errors.append(f"Missing required field: {field_path}")

    # 验证各字段
    properties = schema.get('properties', {})
    for field, field_schema in properties.items():
        if field not in data:
            continue

        field_path = f"{path}.{field}" if path else field
        value = data[field]

        # 类型检查
        expected_type = field_schema.get('type')
        if expected_type:
            type_map = {
                'string': str,
                'integer': int,
                'number': (int, float),
                'boolean': bool,
                'array': list,
                'object': dict,
            }
            expected_python_type = type_map.get(expected_type)
            if expected_python_type and not isinstance(value, expected_python_type):
                errors.append(
                    f"Field {field_path} expected {expected_type}, "
                    f"got {type(value).__name__}"
                )

        # 范围检查
        if 'minimum' in field_schema and isinstance(value, (int, float)):
            if value < field_schema['minimum']:
                errors.append(
                    f"Field {field_path} must be >= {field_schema['minimum']}"
                )

        if 'maximum' in field_schema and isinstance(value, (int, float)):
            if value > field_schema['maximum']:
                errors.append(
                    f"Field {field_path} must be <= {field_schema['maximum']}"
                )

        # 枚举检查
        if 'enum' in field_schema:
            if value not in field_schema['enum']:
                errors.append(
                    f"Field {field_path} must be one of {field_schema['enum']}"
                )

        # 递归验证嵌套对象
        if expected_type == 'object' and isinstance(value, dict):
            nested_schema = field_schema.get('properties')
            if nested_schema:
                errors.extend(_validate_against_schema(
                    value,
                    {'properties': nested_schema, 'required': field_schema.get('required', [])},
                    field_path
                ))

    return errors


def validate_embedding(
    embedding: List[float],
    expected_dim: Optional[int] = None
) -> ValidationResult:
    """
    验证向量嵌入

    Args:
        embedding: 向量嵌入
        expected_dim: 期望的维度

    Returns:
        ValidationResult
    """
    errors: List[str] = []
    warnings: List[str] = []

    if not isinstance(embedding, list):
        return ValidationResult.failure(["embedding must be a list"])

    if len(embedding) == 0:
        return ValidationResult.failure(["embedding cannot be empty"])

    # 检查所有元素是否为数值
    for i, val in enumerate(embedding):
        if not isinstance(val, (int, float)):
            errors.append(f"embedding[{i}] is not numeric: {type(val).__name__}")
            if len(errors) > 10:
                errors.append("... and more errors")
                break

    if errors:
        return ValidationResult.failure(errors)

    # 检查维度
    if expected_dim is not None and len(embedding) != expected_dim:
        errors.append(
            f"embedding dimension mismatch: expected {expected_dim}, "
            f"got {len(embedding)}"
        )

    # 检查是否为零向量
    if all(v == 0 for v in embedding):
        warnings.append("embedding is a zero vector")

    # 检查NaN和Inf
    import math
    for i, val in enumerate(embedding):
        if math.isnan(val):
            errors.append(f"embedding[{i}] is NaN")
        elif math.isinf(val):
            errors.append(f"embedding[{i}] is Inf")

    if errors:
        return ValidationResult.failure(errors)

    return ValidationResult(is_valid=True, errors=[], warnings=warnings)


def validate_user_id(user_id: str) -> ValidationResult:
    """
    验证用户ID

    Args:
        user_id: 用户ID

    Returns:
        ValidationResult
    """
    errors: List[str] = []

    if not isinstance(user_id, str):
        return ValidationResult.failure(["user_id must be a string"])

    if len(user_id) == 0:
        errors.append("user_id cannot be empty")
    elif len(user_id) > 128:
        errors.append("user_id is too long (max 128 chars)")

    # 检查非法字符
    import re
    if not re.match(r'^[a-zA-Z0-9_\-\.@]+$', user_id):
        errors.append(
            "user_id contains invalid characters "
            "(allowed: a-z, A-Z, 0-9, _, -, ., @)"
        )

    if errors:
        return ValidationResult.failure(errors)

    return ValidationResult.success()
